import{_ as a,o as d,c as e,a3 as s}from"./chunks/framework.Cc-oPviL.js";const b=JSON.parse('{"title":"03 · Embedding：把文字变成坐标","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llm/03.md","filePath":"ai/llm/03.md"}'),i={name:"ai/llm/03.md"};function r(l,t,o,n,h,c){return d(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="_03-·-embedding-把文字变成坐标" tabindex="-1">03 · Embedding：把文字变成坐标 <a class="header-anchor" href="#_03-·-embedding-把文字变成坐标" aria-label="Permalink to &quot;03 · Embedding：把文字变成坐标&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>Embedding 是把一段文字变成一串数字（向量），意思相近的文字，向量也相近。</li><li>怎么用「余弦相似度」算两段文字像不像，能用简单数字算一遍。</li><li>为什么 RAG 的检索要靠 Embedding，而不是关键词搜索。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>前两篇讲大模型怎么「接龙」、怎么「看上下文」。这一篇讲<strong>文字怎么变成机器能算的数字</strong>。它是 RAG 的地基：RAG 检索资料，靠的就是比较向量。</p><p>本篇讲 4 个点：① 向量是什么 → ② 相似度怎么算 → ③ 为什么要用向量表示文字 → ④ Embedding 模型和大模型的区别。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>Embedding（嵌入）= 把文字放进一个「意思空间」里，给它一个坐标。意思越接近，坐标离得越近。</strong></p><h2 id="生活类比-地图上的城市" tabindex="-1">生活类比：地图上的城市 <a class="header-anchor" href="#生活类比-地图上的城市" aria-label="Permalink to &quot;生活类比：地图上的城市&quot;">​</a></h2><ul><li>每个城市在地图上有经纬度两个数字。北京和天津离得近，北京和广州离得远。</li><li>Embedding 也是给每段文字一个「坐标」，只不过不是 2 个数，而是几百到几千个数（比如 768 维、1024 维）。</li><li>「猫」和「小猫」离得很近，「猫」和「汽车」离得很远。</li></ul><h2 id="一步步看-用-2-维向量算一遍" tabindex="-1">一步步看：用 2 维向量算一遍 <a class="header-anchor" href="#一步步看-用-2-维向量算一遍" aria-label="Permalink to &quot;一步步看：用 2 维向量算一遍&quot;">​</a></h2><p>真实向量有几百维，我们先用 <strong>2 维</strong>（只有两个数）来理解。假设：</p><table tabindex="0"><thead><tr><th>文字</th><th>向量（示意）</th></tr></thead><tbody><tr><td>「猫」</td><td>(1, 2)</td></tr><tr><td>「小猫」</td><td>(2, 4)</td></tr><tr><td>「汽车」</td><td>(2, −1)</td></tr></tbody></table><p><strong>相似度看「方向」：余弦相似度（Cosine Similarity）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cos = (a·b) / (|a| × |b|)</span></span>
<span class="line"><span>      点积       各自长度相乘</span></span></code></pre></div><ul><li><strong>猫 vs 小猫</strong>：点积 = 1×2 + 2×4 = 10；长度 = √5 和 √20；cos = 10 / √100 = <strong>1.0</strong> → 方向完全一样，最相似。</li><li><strong>猫 vs 汽车</strong>：点积 = 1×2 + 2×(−1) = 0；cos = <strong>0</strong> → 互相垂直，毫无关系。</li></ul><p>记住这条规则：<strong>方向相同是 1，垂直是 0，完全相反是 −1。</strong>「小猫」的向量比「猫」长一倍，但方向一样，所以相似度仍然是 1。这就是为什么要看方向，不看长度。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么要把文字变成向量" tabindex="-1">为什么要把文字变成向量？ <a class="header-anchor" href="#为什么要把文字变成向量" aria-label="Permalink to &quot;为什么要把文字变成向量？&quot;">​</a></h3><ul><li><strong>问题</strong>：计算机只会算数字。直接比较文字只能看「字面是否一样」，「猫」和「喵星人」字面上毫无交集。</li><li><strong>方案</strong>：用一个训练好的模型，把文字映射成向量，让<strong>意思相近的文字向量也相近</strong>。</li><li><strong>好处</strong>：「像不像」变成了一个可以计算的数字，可以排序、可以在百万条里快速找最近的几条。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>把文字变成向量，就能用数学计算语义相似度，从而做语义搜索、聚类、推荐；而且能识别字面不同、意思相同的内容。</p></div><h3 id="为什么-rag-检索用-embedding-而不只用关键词搜索" tabindex="-1">为什么 RAG 检索用 Embedding，而不只用关键词搜索？ <a class="header-anchor" href="#为什么-rag-检索用-embedding-而不只用关键词搜索" aria-label="Permalink to &quot;为什么 RAG 检索用 Embedding，而不只用关键词搜索？&quot;">​</a></h3><ul><li><strong>问题</strong>：用户问「怎么请假」，文档里写的是「休假申请流程」。关键词搜索一个字都对不上，就找不到。</li><li><strong>方案</strong>：问题和文档都转成向量，比较语义距离。</li><li><strong>好处</strong>：同义词、换种说法都能找到。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>关键词只匹配字面，Embedding 匹配语义，「请假」能找到「休假申请」。实际项目里两者常常一起用（混合检索），后面 RAG 篇会讲。</p></div><h3 id="为什么用余弦相似度-而不是直接算距离" tabindex="-1">为什么用余弦相似度，而不是直接算距离？ <a class="header-anchor" href="#为什么用余弦相似度-而不是直接算距离" aria-label="Permalink to &quot;为什么用余弦相似度，而不是直接算距离？&quot;">​</a></h3><ul><li><strong>问题</strong>：一段长文和一段短文，向量的「长度」可能不同，但讲的是同一件事。</li><li><strong>方案</strong>：余弦只看方向、不看长度。</li><li><strong>好处</strong>：不会因为文字长短不同而误判。不少 Embedding 模型输出的向量已经归一化（长度都是 1），这时余弦和点积是一回事。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>余弦相似度只看向量方向，和长度无关，更适合衡量语义是否一致。</p></div><h2 id="embedding-模型-vs-大模型" tabindex="-1">Embedding 模型 vs 大模型 <a class="header-anchor" href="#embedding-模型-vs-大模型" aria-label="Permalink to &quot;Embedding 模型 vs 大模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Embedding 模型</th><th>大模型（聊天用的）</th></tr></thead><tbody><tr><td>输入</td><td>一段文字</td><td>一段文字</td></tr><tr><td>输出</td><td><strong>一个向量</strong>（一串数）</td><td><strong>接着写的文字</strong></td></tr><tr><td>用途</td><td>检索、比较相似度</td><td>生成回答</td></tr><tr><td>在 RAG 里干什么</td><td>找资料</td><td>根据资料写答案</td></tr></tbody></table><p>两者是<strong>不同的模型</strong>，各干各的。换了 Embedding 模型，库里所有文档都要重新算向量，因为不同模型的「坐标系」不通用。</p><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Embedding</td><td>embed 嵌入 + -ing</td><td>把文字「嵌」进一个数字空间，得到向量</td></tr><tr><td>Vector</td><td>向量</td><td>一串有顺序的数字，例如 (1, 2)</td></tr><tr><td>Dimension</td><td>维度</td><td>向量里有几个数，例如 768 维</td></tr><tr><td>Cosine Similarity</td><td>cosine 余弦 + similarity 相似度</td><td>用夹角的余弦衡量两个向量方向是否一致</td></tr><tr><td>Dot Product</td><td>dot 点 + product 乘积</td><td>点积：对应位置相乘再相加</td></tr><tr><td>Normalize</td><td>normal 标准的 + -ize 使…</td><td>归一化：把向量长度缩放成 1</td></tr><tr><td>Semantic Search</td><td>semantic 语义的 + search 搜索</td><td>按意思而不是按字面搜索</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：什么是 Embedding？在 RAG 里起什么作用？</strong></p><blockquote><p>Embedding 是把文本映射为稠密向量的表示，语义相近的文本在向量空间中距离也近。RAG 里，文档切块后用 Embedding 模型转成向量存入向量库；查询时把问题也转成向量，按相似度找出最相关的文档块。</p></blockquote><p><strong>Q：为什么常用余弦相似度？</strong></p><blockquote><p>余弦只衡量方向，不受向量长度影响，更能反映语义是否一致。如果向量已经归一化，余弦相似度等于点积，计算更快。</p></blockquote><p><strong>Q：换了 Embedding 模型要注意什么？</strong></p><blockquote><p>不同模型的向量空间不兼容，必须用新模型把库里所有文档重新向量化；查询和文档必须用同一个模型。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>向量维度越高越好 ✗</strong>：维度高，表达能力强一些，但存储和计算更贵。要看效果和成本。</li><li><strong>相似 ≠ 正确</strong>：向量相似只说明「话题相近」。「年假 5 天」和「年假 10 天」的向量可能非常接近，所以检索结果还需要后续筛选。</li><li><strong>查询和文档要用同一个模型</strong>：用 A 模型存库、用 B 模型查询，结果会完全乱掉。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/02">注意力与 Transformer</a>：Embedding 模型内部通常也是 Transformer。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/02">切块与入库</a>：文档切成块后，每块算一个向量。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/03">检索与重排</a>：检索就是「找余弦相似度最高的几块」。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：用一个生活类比解释 Embedding。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>像地图上的经纬度：每段文字被放到一个「意思空间」里，得到一个坐标（向量）。意思相近的文字坐标离得近，比如「猫」和「小猫」很近，「猫」和「汽车」很远。</p></details><p><strong>Q2：向量 (1, 2) 和 (2, 4) 的余弦相似度是多少？为什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>1</strong>。点积 = 2 + 8 = 10，长度乘积 = √5 × √20 = 10，10/10 = 1。两个向量方向完全相同（一个是另一个的 2 倍），余弦只看方向，所以相似度是 1。</p></details><p><strong>Q3：为什么 RAG 检索要用 Embedding？只用关键词搜索有什么问题？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>关键词搜索只匹配字面，用户问「怎么请假」，文档写「休假申请流程」就搜不到。Embedding 按语义匹配，换种说法也能找到。实际项目常把两者结合（混合检索）。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「地图坐标」的类比解释 Embedding</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能手算两个 2 维向量的余弦相似度</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出余弦相似度的取值含义（1 / 0 / −1）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能讲清「为什么 RAG 检索用 Embedding」（问题 → 方案 → 好处）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出 Embedding 模型和聊天大模型的区别，以及为什么换模型要重建索引</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>有了向量，怎么在几百万条里<strong>快速</strong>找到最近的几条？→ <a href="/study-hub/ai/rag/03">检索与重排</a></li><li>先回到大模型本身：怎么写提示词、怎么调参数让它更听话？→ <a href="/study-hub/ai/llm/04">Prompt 与采样参数</a></li></ul>`,53)])])}const m=a(i,[["render",r]]);export{b as __pageData,m as default};
